INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101001, 1, 'for', '6e27393e-259c-5273-b448-c8c4a01d49fb', 'My daughter is fourteen. Last year she asked me whether her nose looked wrong compared to the girls she follows, girls who sell lip gloss with faces that do not exist in nature. France passed a law in June 2023 requiring influencers to label retouched or filtered commercial photos, with fines up to 75,000 euros, and the sky did not fall. The Dove Self-Esteem Project''s research has found that a large majority of girls say retouched media damages their body image. [Dove](https://www.dove.com/us/en/dove-self-esteem-project.html). When a post is an ad, the viewer deserves to know the product being sold includes a face the seller does not have. We already require ad labels on sponsored posts. This is the same principle, applied to the image itself.', 20, '2026-09-23 12:14:12+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101002, 1, 'for', 'fd549dfd-4b57-5350-965e-35628bcdf570', 'This is not about vanity, it is about fraud. Influencers sell skin creams, teeth whiteners, hair treatments, and diet teas while using the very filters that fake the results. In 2021 the UK''s advertising regulator upheld rulings against brands and influencers for misleadingly filtered beauty ads, and France then made disclosure a legal requirement for commercial content in 2023. [ASA](https://aws1.campaignasia.com/article/ad-regulator-tells-brands-and-influencers-not-to-use-misleading-beauty-filters/466486). If a before-and-after photo is secretly an after-and-filter photo, the consumer is being lied to in exactly the way false-advertising law exists to prevent. Nobody is asking creators to post unflattering photos. The ask is one small label: this image was altered. Honest sellers will survive it. The ones who cannot sell without the filter are proving the point.', 25, '2026-09-24 02:33:34+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101003, 1, 'for', '4c972619-65e6-5a0b-be86-ef7edbf6c5ab', 'I ran a small skincare line and paid micro-influencers for posts. The dirty secret is that everyone in the industry knows the photos are retouched, and everyone pretends they are not. France''s 2023 law covers this with a simple disclosure rule, and compliance has been straightforward: add the label, keep posting. [French economy ministry guidance](https://www.economie.gouv.fr/particuliers/influenceurs). What the rule actually does is level the field. Right now an honest creator who posts real skin loses to the creator with the smoothing filter, and brands reward the lie with bigger checks. Disclosure lets audiences choose with open eyes, and it lets honest creators compete. The platforms already detect filters automatically for their own effects libraries. The technology to flag this exists. We just need the will.', 19, '2026-09-24 02:09:41+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101004, 1, 'against', 'cdfe4d09-7e8c-5048-8b2b-dc5da75e4ba5', 'Define retouched. Is it the beauty filter, or is it also the ring light, the flattering angle, the professional makeup, the photo taken at golden hour? France''s 2023 law tries to draw this line and mostly lands on commercial posts, which sounds tidy until a regulator has to decide whether teeth whitening in Lightroom counts. The UK advertising watchdog has spent years issuing case-by-case rulings because bright lines do not exist here. [ASA](https://aws1.campaignasia.com/article/ad-regulator-tells-brands-and-influencers-not-to-use-misleading-beauty-filters/466486). A law that cannot define its target will be enforced selectively, which means against whoever is unpopular or unlucky. Teach media literacy in schools. Require ad labels for paid content, which we already do. But criminalizing the wrong filter setting is a censor''s fantasy of precision applied to something inherently subjective.', 5, '2026-09-23 21:46:53+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101005, 1, 'against', '424d5afb-cca5-55d7-9994-88a7b8b2b110', 'I am a part-time creator with 40,000 followers, and I edit my own photos between shifts at my actual job. The big agencies pushing for disclosure rules have legal teams and compliance departments. I have a phone and twenty minutes. France''s law threatens fines up to 75,000 euros for violations, and even if small creators are rarely the target, the chilling effect is real: I would rather delete a post than guess wrong about whether my color correction counts as retouching. [French economy ministry guidance](https://www.economie.gouv.fr/particuliers/influenceurs). The irony is that disclosure rules protect the biggest players, who can absorb the compliance cost, while raising the barrier for everyone else. If the goal is honesty, the platforms could add automatic filter labels tomorrow for free. A law with fines is the heaviest possible tool for a problem a toggle could solve.', 13, '2026-09-23 14:15:02+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101006, 1, 'against', '8dc18352-4935-5bb9-bda7-034c410eacb7', 'My kids know filters exist. They learned it the same way they learned wrestling is staged: from adults talking to them, not from a government label. The CDC''s 2023 youth survey found teen girls'' persistent sadness at record highs, and social media is part of that story, but slapping a disclaimer on selfies will not fix what is fundamentally a parenting and education gap. [CDC](https://www.cdc.gov/yrbs). France passed its law in 2023, and French teens still live on TikTok. Labels become wallpaper; we have all learned to ignore cookie banners and terms of service. If we want resilient kids, fund counselors, teach them how images are made, and model better habits at home. A law that outsources parenting to a caption is how you get the appearance of action with none of the results.', 12, '2026-09-23 20:48:51+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101007, 2, 'for', '101e8961-353e-53c6-bbab-3b72ff6e016f', 'Livestock supply chains account for roughly 14.5 percent of human-caused greenhouse gas emissions, according to the UN Food and Agriculture Organization, a share larger than all the world''s cars, planes, and ships combined. [FAO](https://www.fao.org/gleam). A ten-year phaseout is not about ending meat; it is about ending the most concentrated, industrialized way of producing it. We phased out leaded gasoline and ozone-depleting chemicals on similar timelines once the science was clear, and industry adapted faster than the doomsayers predicted. The technology exists: precision fermentation, improved feed additives that cut methane, and higher-welfare systems that already operate at scale in parts of Europe. What is missing is a deadline that forces the transition instead of letting the industry lobby for one more decade of delay.', 8, '2026-09-23 23:16:59+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101008, 2, 'for', '3b4a1013-8ad3-5b73-a858-726c070fcdac', 'I am an ER nurse, and I have watched patients die from infections that used to be routine to treat. The CDC estimates antibiotic-resistant bacteria cause more than 35,000 deaths a year in the US, and a major driver is the routine use of antibiotics in crowded livestock operations to promote growth and prevent disease. [CDC](https://www.cdc.gov/antimicrobial-resistance/). Factory farms are, functionally, incubators for the next resistant superbug. A ten-year phaseout gives producers time to transition to systems that do not need constant drug dosing to keep animals alive in their own filth. This is not a lifestyle debate about your burger. It is about whether we keep burning through our last effective antibiotics so meat can stay a dollar cheaper.', 12, '2026-09-23 12:53:07+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101009, 2, 'for', '4a1b4827-b930-5221-b787-c682c05cd4b0', 'I raise hogs on pasture, 200 head, and I compete against operations with 50,000 animals in confinement that externalize every cost: the manure lagoons, the dead zones, the stench my neighbors downwind from those facilities live with. California voters passed Proposition 12 in 2018 setting minimum space requirements, and the Supreme Court upheld it in 2023. [CDFA](https://www.cdfa.ca.gov/ahfss/AnimalCare/). The market did not collapse. A ten-year phaseout is the only honest version of what Prop 12 started: stop letting the worst actors undercut everyone else by treating animals as machinery. Independent farmers like me would finally compete on quality instead of racing the confinement model to the bottom.', 16, '2026-09-23 18:36:49+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101010, 2, 'against', 'd83da1dd-45fd-5db8-bec8-ef0f536973b4', 'I feed four kids on a grocery budget that is already stretched thin, and chicken is the protein that makes the math work. The Bureau of Labor Statistics tracks food prices closely, and meat and eggs remain the most affordable complete proteins per dollar precisely because of scale. [BLS](https://www.bls.gov/charts/consumer-price-index/consumer-price-index-average-price-data.htm). Phasing out factory farming in ten years means the price of that chicken doubles or triples, and no amount of talk about true cost accounting fills my kids'' lunchboxes. Wealthy shoppers can already buy pasture-raised everything at Whole Foods. A phaseout is a regressive tax on poor families dressed up as virtue, and the people cheering loudest for it are the ones who will never feel the price.', 7, '2026-09-23 17:41:56+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101011, 2, 'against', '82799b7c-befb-53c8-8228-4b8d67243afe', 'There are 8 billion people on this planet, and the UN projects nearly 10 billion by 2050. Factory farming is ugly, but it is also the reason protein became affordable for the global middle class. The FAO''s own data shows demand for animal products rising fastest in developing countries, where a cheap egg can be the difference between adequate nutrition and stunting in children. [FAO](https://www.fao.org/gleam). A ten-year phaseout in the US would not end industrial meat; it would offshore it to countries with weaker environmental and labor standards, exactly as we did with manufacturing. We would get to feel pure while the same farming happens elsewhere, dirtier. If the goal is less suffering and fewer emissions, fund the transition and the technology, but do not ban the system that feeds people before the alternative exists at scale.', 13, '2026-09-23 22:05:37+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101012, 2, 'against', 'ca4fad3f-c547-5465-a567-d0804c7a4408', 'My county has two employers: the school district and the processing plant. The plant buys from 40 contract growers, and every one of those families borrowed against their land to build barns to the integrator''s specs. A ten-year phaseout strands those loans, empties the plant, and turns my town into another hollowed-out main street. The USDA''s own rural data shows how concentrated agricultural employment already is in these regions. [USDA](https://www.usda.gov). Nobody in this debate talks about who pays the growers when the contracts vanish. If you want to end factory farming, buy out the barns, retrain the workers, and show me the plan for the towns. Until then, a phaseout in ten years is a slogan written by people who have never driven past a chicken house at dawn.', 21, '2026-09-23 23:38:51+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101013, 21, 'for', '12d9fecc-5709-5b68-a25b-09139a1abce5', 'The United States spent about $4.5 trillion on health care in 2022, roughly 17 percent of GDP, nearly double what peer nations spend, and still leaves tens of millions underinsured. [CMS](https://www.cms.gov/data-research/statistics-trends-and-reports/national-health-expenditure-data). I know a teacher who did everything right, had insurance through her district, and still ended up with $90,000 in bills after her husband''s cancer because of deductibles, coinsurance, and one out-of-network anesthesiologist. Medical debt is the leading cause of personal bankruptcy in America. Every other wealthy country figured out that you do not let people go broke for getting sick. We pay more for the privilege of worse financial outcomes, and the only people who benefit are the intermediaries skimming between the patient and the doctor.', 4, '2026-09-24 13:26:51+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101014, 21, 'for', 'c995133a-0c49-5845-90c7-d2e8c0f01ed3', 'Americans die younger than citizens of every other high-income country. The Commonwealth Fund regularly ranks the US last among peer nations on access, equity, and outcomes despite spending far more per person. [Commonwealth Fund](https://www.commonwealthfund.org). The UK''s NHS and Canada''s Medicare are not perfect, and their critics love wait-time anecdotes, but no Briton loses their house over a hospital bill and no Canadian gets a surprise $40,000 invoice. A universal system means negotiating drug prices nationally, which is why insulin costs a tenth as much across the border. We already run universal systems for seniors and veterans through Medicare and the VA. The question is not whether government can run health care. It already does, for the most expensive patients, while private insurers profit on the healthy.', 17, '2026-09-24 13:28:33+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101015, 21, 'for', '5077d8a9-4b3e-5b88-b26e-4c1933504fb8', 'I run a 30-person company, and health insurance is my second-largest expense after payroll. Every year the broker comes back with a 12 percent increase and I have to choose between worse coverage and smaller raises. The Kaiser Family Foundation''s annual survey shows the average family premium through employers now exceeds $25,000 a year. [KFF](https://www.kff.org/private-insurance/annual-family-premiums-for-employer-coverage-rise-7-to-average-25572-in-2024-benchmark-survey-finds-after-also-rising-7-last-year/). Universal coverage would take this albatross off every small business in America. My competitors in Canada and Germany do not spend their Octobers haggling with insurers; they spend it running their companies. American businesses are at a structural disadvantage because we tied health care to employment in the 1940s and never untied it. Decouple the two and watch entrepreneurship rise.', 20, '2026-09-24 11:38:00+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101016, 21, 'against', 'ffb4d8da-c5f4-5ec0-ba8f-b4c7b25af7b1', 'Run the math honestly. Universal health care means the $4.5 trillion we spend now gets funded through taxes instead of premiums, and analyses of the major single-payer proposals show middle-class taxes rising by thousands a year. The money does not disappear; it moves to the IRS. And look at what single-payer systems ration: Canada''s median wait for specialist treatment stretched past 27 weeks in recent Fraser Institute reports, and the UK''s NHS has millions on waiting lists. [Fraser Institute](https://www.fraserinstitute.org). Americans are used to getting an MRI this week, not next spring. You can promise universal coverage, but you cannot promise universal, immediate, free care. Something has to give, and it will be timeliness and choice.', 23, '2026-09-24 10:54:13+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101017, 21, 'against', '0657764b-1115-533d-841e-3e79ce8f8bdf', 'The reason the newest cancer drug, the newest surgical robot, the newest mRNA platform comes from America is that our system pays for innovation. The US accounts for a hugely disproportionate share of global medical R&D because companies can earn returns here. Countries with price controls free-ride on American research: they cap what a drug costs while we funded the decade of trials that created it. [OECD](https://www.oecd.org/health/). A government-run system that sets prices by fiat will do what price controls always do: shrink the pipeline. The next Alzheimer''s drug or gene therapy will not be developed by a committee optimizing a budget. If you want the cures of 2040, do not strangle the incentives that produce them.', 13, '2026-09-24 10:12:56+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101018, 21, 'against', '7bfcb97a-8d40-50e6-898a-1c9ac6dbf2e4', 'I get my care through the VA, the closest thing America has to universal government health care, and I have waited four months for a referral that a private clinic would schedule in a week. The VA does good work and I am grateful, but it is also a preview of scale: a federal bureaucracy managing care for 330 million people. The states are already laboratories here: Massachusetts, Hawaii, and others have near-universal coverage through their own designs. [Census](https://www.census.gov). Let states keep experimenting instead of betting the entire country''s health on one federal overhaul that cannot be undone if it fails. Washington struggles to run a website; I do not want it scheduling my surgery.', 12, '2026-09-24 10:45:45+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101019, 22, 'for', '215b110f-c379-52de-8435-8bfdeaa404f3', 'I have been serving for nine years, and my paycheck is a weather report. The federal tipped minimum wage has been $2.13 an hour since 1991, unchanged for over three decades, and everything else depends on the mood of strangers. [DOL](https://www.dol.gov/agencies/whd/fact-sheet/15-tipped-employees-under-the-flsa). Slow Tuesday in February? I make nothing. Research has repeatedly found tipping penalizes Black servers and women, who earn less for the same work because bias rides along with every discretionary dollar. A higher base wage means I can budget, get a car loan, and know what my month looks like. Customers say they tip to reward service, but what they actually reward is whoever matches their idea of friendly. Pay me a wage and let the tip be what it claims to be: optional.', 21, '2026-09-24 13:06:31+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101020, 22, 'for', '15a00d1a-ffdb-5656-967f-d13c7d840734', 'Voters are already deciding this. Washington DC passed Initiative 82 in 2022 to phase out the tipped wage, and California never had one: the state requires the full minimum wage before tips, and its restaurant industry did not collapse. [Ballotpedia](https://ballotpedia.org/Washington,_D.C.,_Initiative_82,_Tip_Credit_Elimination_Initiative_(2022)). The evidence from states without a tip credit is that menu prices adjust modestly, employment holds, and workers get stability. The $2.13 wage is a relic from 1991 that forces workers to beg for the rest of their pay. Seven states already prove the alternative works. The question is not whether restaurants can survive paying a real wage. They do, in a third of the country, right now.', 20, '2026-09-24 10:19:12+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101021, 22, 'for', '8e917d68-eb3d-5016-9083-cd441fe1b6b5', 'I managed restaurants for twelve years, and tipping corrupts everything behind the scenes. Servers making $40 an hour on a Friday fight over sections while the line cooks making $16 burn out and quit, because tips legally cannot be shared with the back of house in most setups. The result is constant turnover where it hurts most. When we tried a service-charge model for one summer, applications for kitchen jobs doubled and the servers who stayed liked knowing their slow shifts were covered. The Bureau of Labor Statistics data on food-service turnover tells the same story industry-wide. [BLS](http://bls.gov/opub/ted/job-openings-and-labor-turnover.htm). Tipping does not reward the team that makes the meal. It rewards whoever carries the plate, and the business bleeds talent everywhere else.', 19, '2026-09-24 11:22:02+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101022, 22, 'against', 'f8a452cb-069e-563b-a5c8-faffd318f87d', 'I make $68,000 a year serving at a mid-range steakhouse, and no higher base wage proposal comes close to replacing that. The activists pushing tip abolition keep talking about the $2.13 wage as if anyone actually takes home $2.13 an hour; with tips I clear $30-plus most nights. When DC started phasing in Initiative 82, plenty of servers opposed it because they did the math. A flat $20 an hour is a pay cut for every good server in a busy restaurant, and the best of us will leave for sales or bartending gigs where performance still pays. You want to help struggling servers? Raise the tipped minimum, enforce wage theft laws, keep the credit. Do not rescue me into a $25,000 pay cut. One DC server wrote about living through the phase-in and reaching the same conclusion. [The 51st](https://51st.news/opinion-initiative-82-was-supposed-to-help-d-c-s-tipped-workers-it-did-the-opposite/).', 9, '2026-09-24 11:44:24+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101023, 22, 'against', '93205977-ca7f-59bc-83aa-c3a7b263a77a', 'People think restaurants are rolling in money. The average full-service margin is 3 to 5 percent, and labor is already the biggest cost. Forcing every server onto a full base wage means raising menu prices 20 to 30 percent overnight, and customers who say they hate tipping will absolutely notice a $24 burger becoming $30. The National Restaurant Association''s industry data consistently shows how thin these margins are. [restaurant.org](https://restaurant.org). What actually happens: owners cut staff, add QR-code ordering, and the server you wanted to help gets replaced by a kiosk. The tip credit is a compromise that keeps dining affordable and keeps humans employed. Kill it and you will get higher prices, fewer jobs, and the same workers earning less.', 9, '2026-09-24 12:47:59+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101024, 22, 'against', 'ee62124c-cc74-5017-95ab-98931ddf1d27', 'Here is the uncomfortable truth: tipping is the only performance pay most service workers will ever see, and service got noticeably worse everywhere it faded. When the tip is guaranteed in the wage, the incentive to hustle on a slammed Saturday night evaporates. I have eaten in countries without tipping cultures and the service is fine but indifferent; nobody is refilling your water before you ask. Tips let customers reward great work directly, server to human, with no manager or algorithm in between. If the problem is the $2.13 floor set in 1991, raise the floor. That fixes exploitation without destroying the one mechanism that makes American service famously attentive. The federal rules themselves confirm the $2.13 cash wage and the employer make-up requirement. [DOL Fact Sheet #15](https://www.dol.gov/agencies/whd/fact-sheets/15-tipped-employees-flsa).', 13, '2026-09-24 10:16:45+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101025, 6, 'for', 'ed3f33e8-2ed5-52fe-9204-d44d3416eef0', 'Here is the angle the flat-fine crowd misses: the problem is not the first violation, it is the fifth. The GDPR already uses a two-tier system, up to 2 percent of global turnover for lesser breaches and 4 percent for the worst, which gives regulators room to start small and escalate. [GDPR](https://gdpr-info.eu). A revenue-linked scale means a company that fixes its practices after one penalty faces a manageable hit, while a serial offender that treats fines as a subscription fee faces an existential one. Flat fines do the opposite: the giant shrugs, pays, and repeats. If we want fines to change behavior instead of just generating headlines, the penalty has to grow with both the company''s size and its rap sheet. Tying the ceiling to global revenue is what makes escalation credible.', 19, '2026-09-23 19:11:18+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101026, 6, 'against', 'b89e3151-b364-5fa5-b619-f5bf7196de27', 'I run a 25-person software company, and a revenue-based fine regime terrifies me in a way it never will terrify a giant. Four percent of global turnover sounds fair until you realize it applies to a startup with one bad quarter and no legal department the same way it applies to a trillion-dollar platform. For us, that fine is death; for them, it is a rounding error they litigate for six years. The GDPR''s enforcement data shows the mega-fines grab headlines while smaller firms quietly drown in compliance costs they cannot spread across billions in revenue. [CMS Law tracker](https://www.cms.law/en/pol/publication/gdpr-enforcement-tracker-report/numbers-and-figures). Revenue linkage was supposed to humble the giants. In practice it entrenches them, because only giants can afford the lawyers to survive it.', 23, '2026-09-23 19:47:02+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101027, 7, 'for', 'cdfe4d09-7e8c-5048-8b2b-dc5da75e4ba5', 'Location data is not like other data. In Carpenter v. United States, the Supreme Court recognized that a detailed record of someone''s movements reveals an all-encompassing picture of their life: the clinic, the protest, the place of worship. [Oyez](https://www.oyez.org/cases/2017/16-402). When a data broker sells that history, the harm already happened; deleting it afterward is like returning a stolen diary after reading it aloud. Payment is the only remedy that acknowledges the violation was personal. The FTC''s action against Outlogic, formerly X-Mode, showed brokers were selling raw location tied to ad IDs that could expose visits to sensitive places. [FTC coverage](https://thehackernews.com/2024/01/ftc-bans-outlogic-x-mode-from-selling.html). If companies must pay the people they tracked, the business model of bulk location sale collapses, which is precisely the point.', 7, '2026-09-23 19:39:16+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101028, 7, 'against', '424d5afb-cca5-55d7-9994-88a7b8b2b110', 'I build apps that use location for legitimate reasons: transit directions, weather alerts, finding a nearby pharmacy. If every misuse allegation triggers automatic payouts, the rational move for a small developer is to strip location features entirely or geo-fence only the biggest markets where legal budgets exist. The FTC''s Outlogic settlement chose the smarter path: ban the sale, mandate deletion, require real consent, and put the company under orders. [FTC coverage](https://thehackernews.com/2024/01/ftc-bans-outlogic-x-mode-from-selling.html). Those remedies actually stop the conduct. Automatic checks, by contrast, mostly enrich claims administrators while users get $1.87 and a privacy notice. Punish the brokers who sell, fix the consent screens, and leave the weather app alone.', 9, '2026-09-23 19:07:15+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101061, 3, 'for', '0a8c60a4-192d-5c06-aff9-8998434c3a2f', 'I work with people coming home from prison, and I watch the same pattern every month. A man gets a job, a bus pass, a place to sleep, and then asks me how to register to vote, because for the first time in years he wants a stake in something bigger than himself. Florida voters understood this in 2018, when [Amendment 4 passed with 64.5% of the vote](https://www.brennancenter.org/our-work/research-reports/voting-rights-restoration-efforts-florida), restoring rights to most people who had finished their sentences. Research keeps finding the same thing: people who vote after release are less likely to go back inside. The [Sentencing Project](https://www.sentencingproject.org/app/uploads/2024/03/Locked-Out-2022-Estimates-of-People-Denied-Voting.pdf) estimates 4.4 million Americans are still locked out of the ballot box, and in Florida alone hundreds of thousands remain barred because of unpaid fines and fees. If the goal is fewer victims and safer streets, handing someone a ballot beats handing them a permanent label.', 10, '2026-09-23 19:00:59+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101062, 3, 'for', 'b7bc4a14-5ec2-51e6-bcc5-21b7e97590b8', 'My classroom has a poster that says every voice matters, and I hate knowing it is a lie for some of my students'' parents. The [Sentencing Project](https://www.sentencingproject.org/app/uploads/2024/03/Locked-Out-2022-Estimates-of-People-Denied-Voting.pdf) reports that 1 in 19 Black adults of voting age is disenfranchised, a rate several times higher than for the rest of the population, because these laws land hardest on communities already over-policed. States like Alabama, Florida, Kentucky, Mississippi, Tennessee, and Virginia keep some of the harshest restrictions in the country, and the racial gap is not an accident of history, it is the predictable result of where enforcement falls. Automatic restoration would not erase those disparities, but it would stop extending them past the prison gate. A democracy that lectures teenagers about civic duty should not then tell their parents the duty ended at sentencing.', 26, '2026-09-24 02:55:44+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
